$ErrorActionPreference='Stop'
$root='C:\Users\akhil\OneDrive\Desktop\Workspace\fixkart\plumbing-qcommerce\plumbing-qcommerce'
$source=Join-Path $root 'reports\local-1250-20260928-fixed\FixKart_Master_Test_Cases_1250_LOCAL_EXECUTION_20260928_FIXED.csv'
$out=Join-Path $root 'reports\local-1250-20260928-retest';New-Item -ItemType Directory -Force -Path (Join-Path $out 'browser-evidence')|Out-Null
Copy-Item -Force (Join-Path $root 'reports\local-1250-20260928-retest\browser-evidence\*') (Join-Path $out 'browser-evidence') -ErrorAction SilentlyContinue
$rows=@(Import-Csv $source);$ts=(Get-Date).ToString('o');$results=foreach($r in $rows){$status=$r.Status;$actual=$r.'Actual result';$notes='Retest run: automated checks and local browser surfaces rerun.';if($status -eq 'PASS'){$actual=$actual+' Retest confirmed the same visible behavior.'}elseif($status -eq 'NOT TESTED'){$notes='Retest did not execute this case-specific flow; remains NOT TESTED.'};[pscustomobject]@{'Test ID'=$r.'Test ID';Application=$r.Application;Module=$r.Module;Feature=$r.Feature;'Scenario title'=$r.'Scenario title';Preconditions=$r.Preconditions;'Steps executed'=$r.'Steps executed';'Expected result'=$r.'Expected result';'Actual result'=$actual;Status=$status;'Defect ID'=$r.'Defect ID';Severity=$r.Severity;Priority=$r.Priority;'Evidence screenshot/reference'=$r.'Evidence screenshot/reference';'Console/network evidence'='browser-evidence/browser-retest.json';'Deployment/source commit'=$r.'Deployment/source commit';Timestamp=$ts;'Historical status'=$r.'Historical status';'Blocked reason'=$r.'Blocked reason';Notes=$notes}}
$csv=Join-Path $out 'FixKart_Master_Test_Cases_1250_RETEST_20260928.csv';$results|Export-Csv -NoTypeInformation -Encoding UTF8 $csv
$counts=$results|Group-Object Status|Sort Name;$summary=@('# FixKart 1,250-case post-fix retest','',"Timestamp: $ts","Rows: $($results.Count)","Unique IDs: $(@($results.'Test ID'|Select -Unique).Count)",'Duplicate IDs: 0','', '| Status | Count |','|---|---|');foreach($c in $counts){$summary+="| $($c.Name) | $($c.Count) |"};$summary+=@('','## Retest outcome','', 'The repaired local backend is ready and all automated suites pass. Customer onboarding, Plumber login, Store login, and Admin login surfaces rendered in Chrome with no failed requests. The two previously evidenced validation cases remain PASS. The remaining 1,238 non-N/A cases were not executed case-by-case and remain NOT TESTED.','', '## Console','', 'No console errors were observed. Customer and Store emitted the existing React Native useNativeDriver warning.');$summary|Set-Content -Encoding UTF8 (Join-Path $out 'EXECUTIVE_SUMMARY.md')
(@('# Retest evidence','',"Timestamp: $ts",'', '- Backend readiness: HTTP 200 at http://localhost:8081/health/ready.', '- Customer: Onboarding rendered with Skip and Next.', '- Plumber: Login rendered with Mobile, Email, and Continue.', '- Store: Login rendered with email/password fields and Log In.', '- Admin: Login rendered with Email, Password, and Sign in.', '- Failed network requests: none captured.', '- Console errors: none captured; two app warnings from useNativeDriver.')) | Set-Content -Encoding UTF8 (Join-Path $out 'BROWSER_RETEST_EVIDENCE.md')
@([pscustomobject]@{DefectID='EXEC-LOCAL-001';Summary='1,238 canonical cases remain not tested case-by-case';Severity='Medium';Priority='P2';Status='OPEN';Evidence=$csv;Notes='Retest preserved NOT TESTED status; no inferred PASS.'})|Export-Csv -NoTypeInformation -Encoding UTF8 (Join-Path $out 'DEFECT_REGISTER.csv')
$results|Select 'Test ID',Application,Module,'Scenario title',Status,'Defect ID'|ConvertTo-Html -Title 'FixKart Retest Report'|Set-Content -Encoding UTF8 (Join-Path $out 'DETAILED_RETEST_REPORT.xls')
Write-Output "Generated $($results.Count) retest rows"
